/**
 * Etsy ShopRefund → canonical Refund.
 *
 * Etsy embeds refund records directly on the ShopReceipt response under a
 * `refunds` array. There is no dedicated refund CRUD endpoint — refunds
 * are generated by Etsy's case-management and payment systems and returned
 * as read-only data when fetching a receipt.
 *
 * Derived from: GET /shops/{shop_id}/receipts/{receipt_id}
 *
 * Key mapping decisions:
 *  - Synthetic id: `${receipt_id}:${index}` — refunds have no dedicated id.
 *  - `orderId` is the receipt_id (stringified).
 *  - `amount` is the ShopRefund `amount` Money object (Etsy major-unit format).
 *  - `reason` maps from ShopRefund `reason` string.
 *  - `note` maps from ShopRefund `note_from_issuer`.
 *  - `processedAt` / `createdAt` from `created_timestamp` epoch seconds.
 */

import type { Refund } from '../../../schema/refund'
import type { RawEtsyMoney } from './product'
import type { RawEtsyReceipt } from './order'
import { majorToMinor } from '../../../schema/shared'

// ── Raw shapes ───────────────────────────────────────────────────────────────

export interface RawEtsyRefund {
  amount?: RawEtsyMoney
  created_timestamp?: number
  reason?: string
  note_from_issuer?: string
  status?: string
  [key: string]: unknown
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function etsyMoneyToCanonical(
  money: RawEtsyMoney | undefined,
): { amount: number; currency: string } | undefined {
  if (!money || money.divisor === 0) return undefined
  return {
    amount: majorToMinor(money.amount / money.divisor, money.currency_code),
    currency: money.currency_code,
  }
}

function tsToIso(ts: number | undefined): string | undefined {
  if (ts == null) return undefined
  return new Date(ts * 1000).toISOString()
}

// ── Transform ────────────────────────────────────────────────────────────────

export function transformRefund(
  receipt: RawEtsyReceipt,
  refund: RawEtsyRefund,
  index: number,
): Refund {
  const receiptId = String(receipt.receipt_id)
  const id = `${receiptId}:refund:${index}`
  const processedAt = tsToIso(refund.created_timestamp)

  return {
    id,
    orderId: receiptId,
    amount: etsyMoneyToCanonical(refund.amount),
    reason: refund.reason ?? undefined,
    note: refund.note_from_issuer ?? undefined,
    processedAt,
    createdAt: processedAt,
    metadata: {
      status: refund.status,
      receipt_id: receipt.receipt_id,
      index,
    },
  }
}

/**
 * Extract all refunds from a receipt response.
 */
export function transformRefunds(receipt: RawEtsyReceipt): Refund[] {
  const refunds = (receipt.refunds ?? []) as RawEtsyRefund[]
  return refunds.map((r, i) => transformRefund(receipt, r, i))
}
